class AsyncMessagesBatches(AsyncAPIResource):
    """The /v1/messages/batches, /v1/messages/batches/{id}, /v1/messages/batches/{id}/cancel, /v1/messages/batches/{id}/results routes."""

    def __init__(self, client: AsyncAPIClient) -> None:
        super().__init__(client)

    async def create(
        self,
        *,
        requests: Sequence[MessageBatchRequest],
        idempotency_key: str | None = None,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | None = None,
        max_retries: int | None = None,
    ) -> MessageBatch:
        """Create a message batch.

        POST /v1/messages/batches; needs the orbtr.messages.batch.create scope.

        Args:
            requests: The requests to run.
            idempotency_key: The Idempotency-Key; one is made when absent, and every retry sends the same key.
        """
        return await self._client._request_json(
            "POST",
            "/v1/messages/batches",
            body=compact({"requests": requests}),
            parse=MessageBatch.from_dict,
            idempotent=True,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries, idempotency_key=idempotency_key),
        )

    async def list(
        self,
        *,
        after_id: str | None = None,
        limit: int | None = None,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | None = None,
        max_retries: int | None = None,
    ) -> MessageBatchList:
        """List message batches, newest first.

        GET /v1/messages/batches; needs the orbtr.messages.batch.list scope.

        Args:
            after_id: Start after this batch.
            limit: The most batches to return.
        """
        return await self._client._request_json(
            "GET",
            "/v1/messages/batches",
            query=compact({"after_id": after_id, "limit": limit}),
            parse=MessageBatchList.from_dict,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )

    async def retrieve(
        self,
        id: str,
        /,
        *,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | None = None,
        max_retries: int | None = None,
    ) -> MessageBatch:
        """Read one message batch.

        GET /v1/messages/batches/{id}; needs the orbtr.messages.batch.read scope.
        """
        return await self._client._request_json(
            "GET",
            f"/v1/messages/batches/{quote(id, safe='')}",
            parse=MessageBatch.from_dict,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )

    async def cancel(
        self,
        id: str,
        /,
        *,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | None = None,
        max_retries: int | None = None,
    ) -> MessageBatch:
        """Cancel a message batch's unfinished requests.

        POST /v1/messages/batches/{id}/cancel; needs the orbtr.messages.batch.cancel scope.
        """
        return await self._client._request_json(
            "POST",
            f"/v1/messages/batches/{quote(id, safe='')}/cancel",
            parse=MessageBatch.from_dict,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )

    async def results(
        self,
        id: str,
        /,
        *,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | None = None,
        max_retries: int | None = None,
    ) -> list[MessageBatchResult]:
        """Fetch a batch's results, one per request.

        GET /v1/messages/batches/{id}/results; needs the orbtr.messages.batch.results scope.
        """
        return await self._client._request_ndjson(
            "GET",
            f"/v1/messages/batches/{quote(id, safe='')}/results",
            parse=MessageBatchResult.from_dict,
            options=RequestOptions(extra_headers=extra_headers, timeout=timeout, max_retries=max_retries),
        )


class Resources:
    """The API's resources on a client, one per top-level path segment."""

    messages: Messages
    models: Models
    embeddings: Embeddings
    chat: Chat
    completions: Completions

    def _init_resources(self) -> None:
        client = cast("SyncAPIClient", self)
        self.messages = Messages(client)
        self.models = Models(client)
        self.embeddings = Embeddings(client)
        self.chat = Chat(client)
        self.completions = Completions(client)


class AsyncResources:
    """The API's resources on an async client, one per top-level path segment."""

    messages: AsyncMessages
    models: AsyncModels
    embeddings: AsyncEmbeddings
    chat: AsyncChat
    completions: AsyncCompletions

    def _init_resources(self) -> None:
        client = cast("AsyncAPIClient", self)
        self.messages = AsyncMessages(client)
        self.models = AsyncModels(client)
        self.embeddings = AsyncEmbeddings(client)
        self.chat = AsyncChat(client)
        self.completions = AsyncCompletions(client)
